def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.35)
        return max(0.0, float(bid))

    prev_bids = []
    prev_live_bids = []
    desperate_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_opp += 1
        prev = opp.get('previous_trace') or {}
        bid_y = prev.get('bid')
        if bid_y is not None:
            prev_bids.append(float(bid_y))
            if prev.get('status') != 'dead':
                prev_live_bids.append(float(bid_y))

    max_prev = max(prev_bids) if prev_bids else 0.0
    max_live_prev = max(prev_live_bids) if prev_live_bids else max_prev
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    tight_supply = supply <= 16.0
    ample_supply = supply >= 22.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2
    if tight_supply:
        urgency += 1
    if desperate_opp >= 2:
        urgency += 1

    if urgency >= 5:
        target = max(DAILY_SALARY * 1.15, max_live_prev + 8.0)
    elif urgency >= 3:
        target = max(DAILY_SALARY * 0.9, max_live_prev + 3.0)
    else:
        if ample_supply:
            if max_prev >= DAILY_SALARY * 1.8:
                target = DAILY_SALARY * 0.28
            elif max_prev >= DAILY_SALARY * 1.2:
                target = DAILY_SALARY * 0.38
            else:
                target = max(DAILY_SALARY * 0.32, avg_prev * 0.45)
        else:
            if max_prev >= DAILY_SALARY * 1.8:
                target = DAILY_SALARY * 0.42
            elif max_prev >= DAILY_SALARY * 1.2:
                target = max(DAILY_SALARY * 0.52, avg_prev * 0.55)
            else:
                target = max(DAILY_SALARY * 0.48, max_live_prev + 1.5)

    if rich_opp >= 2 and not ample_supply:
        target += 6.0
    if day >= 8 and (hp <= 5 or no_water_days >= 1):
        target += 8.0

    soft_cap = budget
    if urgency <= 2:
        soft_cap = min(soft_cap, DAILY_SALARY * 0.95)
    elif urgency == 3:
        soft_cap = min(soft_cap, DAILY_SALARY * 1.25)
    else:
        soft_cap = min(soft_cap, DAILY_SALARY * 1.8)

    bid = min(target, soft_cap)
    if hp >= 8 and no_water_days == 0 and ample_supply and max_prev >= DAILY_SALARY * 1.5:
        bid = min(bid, DAILY_SALARY * 0.25)

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents only
    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    # If no one is alive, conserve budget
    if not alive:
        return max(0.0, min(float(my_status.get('budget', 0.0)), DAILY_SALARY * 0.4))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Read yesterday bids from traces for immediate reaction
    prev_bids = []
    for _, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how competitive the market was
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_highest_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_highest_prev_bid = sorted_b[1]

    # Identify who is under pressure (no_water_days high or hp low) to anticipate their next bid
    pressure = 0
    for _, opp in alive:
        opp_hp = float(opp.get('hp', 0.0))
        opp_no = int(opp.get('no_water_days', 0))
        if opp_no >= 2 or opp_hp <= 2:
            pressure += 1

    # Baseline bid: aim to be competitive but not reckless
    # If I'm low hp or have missed water, increase bid to secure water.
    if my_hp <= 2.0 or no_water_days >= 2:
        base = DAILY_SALARY * 0.85
    elif my_hp <= 4.0 or no_water_days == 1:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.52

    # If market was hot yesterday, slightly overbid the likely leader
    # Cindy showed very high average bid and survived; match the pattern when competition is high.
    hot_market = highest_prev_bid >= DAILY_SALARY * 0.9
    if hot_market:
        target = highest_prev_bid + 2.0
    else:
        # If not too hot, try to beat second tier
        target = max(base, second_highest_prev_bid + 1.5)

    # If many opponents are under pressure, expect higher bids; raise target modestly
    if pressure >= 2:
        target *= 1.05

    # Scale with remaining supply fraction: lower supply => higher chance to be contested
    # supply in [15,25]; map to multiplier in [1.10, 0.95]
    if supply <= 0:
        supply_mult = 1.0
    else:
        supply_clamped = max(MIN_SUPPLY, min(MAX_SUPPLY, supply))
        supply_mult = 1.10 - (supply_clamped - MIN_SUPPLY) * (0.15 / (MAX_SUPPLY - MIN_SUPPLY))

    bid = target * supply_mult

    # Never exceed budget; also avoid bidding above what would be wasteful late/early
    # Late game: bid more aggressively to avoid elimination.
    if day >= 8:
        bid *= 1.08

    bid = max(0.0, min(my_budget, bid))

    # Ensure some minimal bid if budget allows
    if my_budget > 0 and bid < DAILY_SALARY * 0.15:
        bid = min(my_budget, DAILY_SALARY * 0.15)

    return float(bid)

